func TestTSOMonotonicConcurrent(t *testing.T) {
	o := NewTSO(0)
	const goroutines, per = 32, 200
	var wg sync.WaitGroup
	results := make([][]int64, goroutines)
	for g := 0; g < goroutines; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			rs := make([]int64, per)
			for i := 0; i < per; i++ {
				rs[i] = o.Allocate()
			}
			results[g] = rs
		}(g)
	}
	wg.Wait()

	seen := make(map[int64]bool)
	for _, rs := range results {
		for i, ts := range rs {
			if seen[ts] {
				t.Fatalf("duplicate timestamp %d", ts)
			}
			seen[ts] = true
			if i > 0 && rs[i] <= rs[i-1] {
				t.Fatalf("non-monotonic within goroutine: %d then %d", rs[i-1], rs[i])
			}
		}
	}
}

func TestCommitWaitHonoursUncertaintyBound(t *testing.T) {
	const eps = 3 * time.Millisecond
	s := New(eps)
	start := time.Now()

	tx := s.Begin()
