func TestSnapshotIsolation(t *testing.T) {
	s := New(0)
	seed(t, s, map[string]string{"a": "1"})

	t1 := s.Begin() // old snapshot

	seed(t, s, map[string]string{"a": "2"}) // committed after t1's snapshot

	v, err := t1.Get("a")
	if err != nil {
		t.Fatalf("snapshot read: %v", err)
	}
	if string(v) != "1" {
		t.Fatalf("snapshot read = %q, want \"1\"", v)
	}
	t1.Rollback()
}

func TestWriteWriteConflict(t *testing.T) {
	s := New(0)
	seed(t, s, map[string]string{"k": "0"})

	t1 := s.Begin()
	t2 := s.Begin()
	if err := t1.Put("k", []byte("1")); err != nil {
		t.Fatal(err)
	}
	if err := t2.Put("k", []byte("2")); err != nil {
		t.Fatal(err)
	}
	if err := t1.Commit(); err != nil {
		t.Fatalf("first writer should win: %v", err)
	}
	err := t2.Commit()
	if !errors.Is(err, ErrWriteConflict) {
		t.Fatalf("second writer err = %v, want ErrWriteConflict", err)
	}
	if !Retryable(err) {
		t.Fatalf("write conflict must be retryable")
	}
}

// TestReadConflictRecordedAfterCommit covers the soundness hole where a
// snapshot predates a commit but the read happens after the commit.  The
// writer can no longer discover the reader, so the reader must record the
// rw-edge itself.
func TestReadConflictRecordedAfterCommit(t *testing.T) {
	s := New(0)
	seed(t, s, map[string]string{"a": "1", "b": "1"})

	reader := s.Begin()
	writer := s.Begin()
	if _, err := writer.Get("b"); err != nil {
		t.Fatal(err)
	}
	if err := writer.Put("a", []byte("2")); err != nil {
		t.Fatal(err)
	}
	if err := writer.Commit(); err != nil {
		t.Fatalf("writer commit: %v", err)
	}

	v, err := reader.Get("a") // old snapshot => sees the superseded value
	if err != nil {
		t.Fatal(err)
	}
	if string(v) != "1" {
		t.Fatalf("reader saw %q, want \"1\"", v)
	}
	if _, ok := reader.outTo[writer.id]; !ok {
		t.Fatalf("missing rw-edge reader ->rw writer")
	}
	if _, ok := writer.inFrom[reader.id]; !ok {
		t.Fatalf("missing reverse edge writer.inFrom[reader]")
	}
	reader.Rollback()
}

